"""Documentacao da 219a leva. Uso: python docs.py"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'engenharia-reversa'))
from gen_docs import fazer, leia, cadeia, prova_save, REF_JOGO, CARREIRA_PT, CARREIRA_EN

N = 219
R = [('filtro_do_jogo_salvo', 'check_saved_game_file', '0x838e10', 'Setup.cpp', 'cdecl', 'filtro da caixa de arquivos dos jogos salvos: 1 se o contêiner tem o id 0x16 (.sav), senão 2 (só ax); caminho nulo dá a caixa de erro', 'file box filter for saved games: 1 if the container has id 0x16 (.sav), else 2 (ax only); a null path gives the error box'), ('filtro_do_inicio_rapido', 'check_quick_start_file', '0x839290', 'Setup.cpp', 'cdecl', 'filtro da caixa de arquivos do início rápido: 1 se o contêiner tem o id 0x17 (.qst) e a versão gravada é a do exe, senão 2 (só ax)', 'file box filter for quick starts: 1 if the container has id 0x17 (.qst) and the saved version is the exe one, else 2 (ax only)'), ('versao_do_jogo_salvo_valida', 'valid_saved_game_version', '0x838eb0', 'Setup.cpp', 'cdecl', 'abre o general.dat do contêiner, lê a versão e o resumo (0xf70 ou 0xf74 bytes) e devolve 1 se o texto da versão do resumo é o do exe; quando dá certo não fecha o item (como a original)', 'opens the container general.dat, reads the version and the summary (0xf70 or 0xf74 bytes) and returns 1 if the summary version text is the exe one; on success it does not close the item (as the original)'), ('gravar_regras_fifa', 'save_fifa_transfer_rules', '0x8395b0', 'Setup.cpp', 'cdecl', 'grava o último item do save, fifa_transfer_rules.zip: 2 bytes ([0xae233c] e a regra em vigor [0xa83608]); erros dão a caixa "Error"', 'writes the last saved game item, fifa_transfer_rules.zip: 2 bytes ([0xae233c] and the rule in force [0xa83608]); errors give the "Error" box'), ('carregar_regras_fifa', 'load_fifa_transfer_rules', '0x839760', 'Setup.cpp', 'cdecl', 'lê os 2 bytes de fifa_transfer_rules.zip; se o primeiro é 1, a regra em vigor vira 5', 'reads the 2 bytes of fifa_transfer_rules.zip; if the first is 1, the rule in force becomes 5'), ('montar_resumo_do_save', 'build_save_game_summary', '0x591f80', 'file_screens.cpp', 'cdecl', 'monta o resumo do general.dat: as nações ativas (dois grupos), os técnicos humanos com clube e nação, a data do jogo, a versão, o tempo de jogo e o time()', 'builds the general.dat summary: the active nations (two groups), the human managers with club and nation, the game date, the version, the play time and time()'), ('gravar_banco_no_save', 'save_database_for_game', '0x524d30', 'Database.cpp', 'cdecl', 'passo 1 do save_game_data: save_database(save, 1, a4, tipo), as tabelas do banco no contêiner', 'save_game_data step 1: save_database(save, 1, a4, type), the database tables into the container'), ('carregar_banco_do_save', 'load_database_from_stream', '0x524d10', 'Database.cpp', 'cdecl', 'passo 2 do load_game_data: load_database(save, compartilhado, 1), o banco lido do contêiner', 'load_game_data step 2: load_database(save, shared, 1), the database read from the container'), ('liberar_dados_do_jogo', 'free_game_data', '0x82ff40', 'Setup.cpp', 'cdecl', 'solta as telas, destrói os subsistemas guardados em globais (destrutor + delete, free, destrutor virtual) na ordem da original, apaga os *.tmp, libera as tabelas do banco, volta a data do jogo e zera três marcas; devolve 1', 'releases the screens, destroys the subsystems held in globals (destructor + delete, free, virtual destructor) in the original order, deletes the *.tmp files, frees the database tables, resets the game date and clears three flags; returns 1')]
ESCAPADAS = {  # nome: (explicação pt, explicação en)
    'sv2_banco_a4': ('a cópia da 0x524d30 está desligada (DESLIGADAS: o save_database que ela chama grava 408 bytes de locais sem valor no index.dat e, chamado da cópia na pilha particular, o lixo muda), então a mutação não roda', 'the 0x524d30 copy is switched off (DESLIGADAS: the save_database it calls writes 408 bytes of unset locals into index.dat and, called from the copy on the private stack, the garbage changes), so the mutation does not run'),
}
tot, ac, esc, ok = cadeia(N)
assert ok, 'cadeia sem a referencia'
assert set(esc) <= set(ESCAPADAS), ('explicar as escapadas', esc)
lac_pt = ' '.join(f'`{e}` escapou: {ESCAPADAS[e][0]}.' for e in esc) + (' (lacuna em `PENDENCIAS.md`)' if esc else '')
lac_en = ' '.join(f'`{e}` escaped: {ESCAPADAS[e][1]}.' for e in esc) + (' (gap in `PENDENCIAS.en.md`)' if esc else '')
PS = prova_save(N)  # leva do save: mutações e prova pelo .qst gravado com e sem as rotinas (cadeia.sh)
VIA_PT = 'pela prova do save' if PS else 'pela carreira até 2002-06-01, confirmando no modo comparação as que escapam'
VIA_EN = 'by the save proof' if PS else 'by the career to 2002-06-01, confirming the escaped ones in comparison mode'
PS_PT = f'Prova do save (o .qst com e sem as rotinas): {PS}. ' if PS else ''
PS_EN = f'Save proof (the .qst with and without the routines): {PS.replace("IGUAL", "EQUAL").replace("DIFERENTE", "DIFFERENT")}. ' if PS else ''
M = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_PT}): {ac} acusadas. {lac_pt} {PS_PT}"
     f"Jogo real comparando até 2002-01-01: 0 divergências ({REF_JOGO}). Carreiras Rust ×2 e original até 2002-06-01: {CARREIRA_PT}")
ME = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_EN}): {ac} caught. {lac_en} {PS_EN}"
      f"Real game comparing to 2002-01-01: 0 divergences ({REF_JOGO}). Rust ×2 and original careers to 2002-06-01: {CARREIRA_EN}")
fazer(N, 566, 566 + len(R), 'o save: os filtros da caixa de arquivos (o jogo salvo, o início rápido e a versão); o save: as regras FIFA de transferência (gravar e carregar) e o resumo do save; o save: as ligações com o banco (gravar e carregar) e liberar os dados do jogo', 'the saved game: the file box filters (saved game, quick start and version); the saved game: the FIFA transfer rules (save and load) and the save summary; the saved game: the database links (save and load) and freeing the game data',
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, d, _ in R],
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, _, d in R],
      M, ME, [(a, g) for a, g, *_ in R], "'posicao_no_conteiner': 'position_in_container',", secao=('Simulação', 'Simulation'))
leia(N, 'o save: os filtros da caixa de arquivos (o jogo salvo, o início rápido e a versão); o save: as regras FIFA de transferência (gravar e carregar) e o resumo do save; o save: as ligações com o banco (gravar e carregar) e liberar os dados do jogo', 'the saved game: the file box filters (saved game, quick start and version); the saved game: the FIFA transfer rules (save and load) and the save summary; the saved game: the database links (save and load) and freeing the game data', [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en,
     campos=[('contêiner (arquivo) +4: id do arquivo (0x16 .sav, 0x17 .qst); valor; lê, pelo 0x9331c0 (filtro_do_jogo_salvo, filtro_do_inicio_rapido)', 'container (file) +4: archive id (0x16 .sav, 0x17 .qst); value; reads, through 0x9331c0 (filtro_do_jogo_salvo, filtro_do_inicio_rapido)'), ('general.dat +0: versão do save; valor (|v| < 0x3e027 = resumo antigo de 0xf70 bytes); lê (versao_do_jogo_salvo_valida)', 'general.dat +0: save version; value (|v| < 0x3e027 = old 0xf70-byte summary); reads (versao_do_jogo_salvo_valida)'), ('general.dat +4: resumo do save (0xf70 ou 0xf74 bytes; o de build_save_game_summary); bytes; lê (versao_do_jogo_salvo_valida)', 'general.dat +4: save summary (0xf70 or 0xf74 bytes; the build_save_game_summary one); bytes; reads (versao_do_jogo_salvo_valida)'), ('resumo do save +0x7d0: texto da versão do exe que gravou; texto; lê e compara com 0x90d130 (versao_do_jogo_salvo_valida)', 'save summary +0x7d0: version text of the exe that saved; text; reads and compares with 0x90d130 (versao_do_jogo_salvo_valida)'), ('[0xae24d0], [0xae28bc], [0xae26c4] textos da caixa de erro; texto; grava (versao_do_jogo_salvo_valida, nos erros)', '[0xae24d0], [0xae28bc], [0xae26c4] error box texts; text; writes (versao_do_jogo_salvo_valida, on errors)'), ('[0xae233c] primeiro byte das regras FIFA (1 = regra 5 ao carregar); valor; lê (gravar_regras_fifa) e grava (carregar_regras_fifa)', '[0xae233c] first FIFA rules byte (1 = rule 5 on load); value; reads (gravar_regras_fifa) and writes (carregar_regras_fifa)'), ('[0xa83608] regra FIFA de transferência em vigor (10 no exe); valor; lê (gravar_regras_fifa) e grava, 5 se [0xae233c] = 1 (carregar_regras_fifa)', '[0xa83608] FIFA transfer rule in force (10 in the exe); value; reads (gravar_regras_fifa) and writes, 5 if [0xae233c] = 1 (carregar_regras_fifa)'), ('fifa_transfer_rules.zip (item do save): os 2 bytes acima; bytes; grava (gravar_regras_fifa) e lê (carregar_regras_fifa)', 'fifa_transfer_rules.zip (saved game item): the 2 bytes above; bytes; writes (gravar_regras_fifa) and reads (carregar_regras_fifa)'), ('tabela de ligas [0xb63d60] (0x23 itens de 0x48) +0: nação; ponteiro; lê (montar_resumo_do_save)', 'league table [0xb63d60] (0x23 items of 0x48) +0: nation; pointer; reads (montar_resumo_do_save)'), ('nação +0x11c: bits 2 e 1 (os dois grupos de nações do resumo); valor; lê (montar_resumo_do_save)', 'nation +0x11c: bits 2 and 1 (the two summary nation groups); value; reads (montar_resumo_do_save)'), ('nação/clube +0x38: nome; texto; lê (montar_resumo_do_save)', 'nation/club +0x38: name; text; reads (montar_resumo_do_save)'), ('pessoa (0x6e) +0x5f: técnico humano (1); valor; lê (montar_resumo_do_save)', 'staff (0x6e) +0x5f: human manager (1); value; reads (montar_resumo_do_save)'), ('pessoa +0x39: clube; ponteiro; lê (montar_resumo_do_save)', 'staff +0x39: club; pointer; reads (montar_resumo_do_save)'), ('pessoa +0x24: seleção (nação); ponteiro; lê (montar_resumo_do_save)', 'staff +0x24: national team (nation); pointer; reads (montar_resumo_do_save)'), ('[0xae2364] quantidade de pessoas, [0xae23bc] tabela de pessoas; valor, ponteiro; lê (montar_resumo_do_save)', '[0xae2364] staff count, [0xae23bc] staff table; value, pointer; reads (montar_resumo_do_save)'), ('[0xae2c90] data do jogo; valor; lê (montar_resumo_do_save)', '[0xae2c90] game date; value; reads (montar_resumo_do_save)'), ('[0xdd7140] tempo de jogo acumulado, [0xdd7144] último time(); valor; lê e grava (montar_resumo_do_save)', '[0xdd7140] accumulated play time, [0xdd7144] last time(); value; reads and writes (montar_resumo_do_save)'), ('resumo do save +0 / +0x3e8: nações (bit 2 / bit 1); texto; grava (montar_resumo_do_save)', 'save summary +0 / +0x3e8: nations (bit 2 / bit 1); text; writes (montar_resumo_do_save)'), ('resumo do save +0x7d0: versão do exe; texto; grava (montar_resumo_do_save)', 'save summary +0x7d0: exe version; text; writes (montar_resumo_do_save)'), ('resumo do save +0x7e4 + 0x78 vezes i (i < 16): nome do técnico humano; texto; grava (montar_resumo_do_save)', 'save summary +0x7e4 + 0x78 times i (i < 16): human manager name; text; writes (montar_resumo_do_save)'), ('resumo do save +0x820 + 0x78 vezes i: "clube / nação" do técnico; texto; grava, só para humano (montar_resumo_do_save)', 'save summary +0x820 + 0x78 times i: manager "club / nation"; text; writes, human only (montar_resumo_do_save)'), ('resumo do save +0xf64: data do jogo; valor; grava (montar_resumo_do_save)', 'save summary +0xf64: game date; value; writes (montar_resumo_do_save)'), ('resumo do save +0xf6c / +0xf70: tempo de jogo e time(); valor (relógio); grava (montar_resumo_do_save)', 'save summary +0xf6c / +0xf70: play time and time(); value (clock); writes (montar_resumo_do_save)'), ('[0xb67a50], [0xb6b7c8], [0xae2a60], [0xb67a44], [0xad9da8], [0xad9dac], [0xde1d08], [0xae28f0], [0xde1f44], [0xad9c60], [0xde1f54], [0xb63d28], [0xae2a3c], [0xad9c6c], [0xae2a30], [0xb7433c], [0xdd7ef4], [0xb74318], [0xde2f70], [0xde1f58], [0xae1000], [0xdd7f00], [0xb6b7c0], [0xb74350], [0xb5e134], [0xae2a58], [0xb63c98], [0xb74448], [0xb7431c], [0xae1050], [0xae2a38], [0xb7434c], [0xb74340], [0xdd7ee4], [0xde2f74], [0xb74430] subsistemas do jogo; ponteiro; lê, destrói e grava 0 (liberar_dados_do_jogo)', 'game subsystems; pointer; reads, destroys and writes 0 (liberar_dados_do_jogo)'), ('[0xae2c74] (amistosos), [0xb74434] objetos com destrutor virtual; ponteiro; lê, destrói e grava 0 (liberar_dados_do_jogo)', '[0xae2c74] (friendlies), [0xb74434] objects with a virtual destructor; pointer; reads, destroys and writes 0 (liberar_dados_do_jogo)'), ('[0xadadfc] (e [0xadadf8]), [0xae2d0c], [0xae2d14], [0xae2d1c], [0xae2d20], [0xae2d24], [0xae2338], [0xdd7ef0] vetores soltos; ponteiro; lê, libera e grava 0 (liberar_dados_do_jogo)', '[0xadadfc] (and [0xadadf8]), [0xae2d0c], [0xae2d14], [0xae2d1c], [0xae2d20], [0xae2d24], [0xae2338], [0xdd7ef0] loose arrays; pointer; reads, frees and writes 0 (liberar_dados_do_jogo)'), ('[0xae2c90] data do jogo; valor; grava (0x54a130 com 1, 0, 2001, -1) (liberar_dados_do_jogo)', '[0xae2c90] game date; value; writes (0x54a130 with 1, 0, 2001, -1) (liberar_dados_do_jogo)'), ('[0xae2c88] (byte), [0xdd711c], [0xdd7130] marcas do jogo; valor; grava 0 (liberar_dados_do_jogo)', '[0xae2c88] (byte), [0xdd711c], [0xdd7130] game flags; value; writes 0 (liberar_dados_do_jogo)')], interessa=['SGE', 'CMRTE'])
